<?php
require_once __DIR__.'/includes/bootstrap.php';require_login();$q=trim($_GET['q']??'');$st=$pdo->prepare("SELECT s.*,COALESCE(c.name,'Walk-in customer') customer,u.name staff FROM sales s LEFT JOIN customers c ON c.id=s.customer_id LEFT JOIN users u ON u.id=s.user_id WHERE s.invoice_no LIKE ? OR COALESCE(c.name,'Walk-in customer') LIKE ? ORDER BY s.id DESC LIMIT 200");$st->execute(["%$q%","%$q%"]);$rows=$st->fetchAll();layout_start('Sales & bills','sales');?>
<section class="panel table-panel"><div class="panel-head"><div><h3>Transaction history</h3><p class="muted">Invoices and payment status</p></div><form class="search-form"><input name="q" value="<?=h($q)?>" placeholder="Invoice or customer…"><button class="btn secondary">Search</button></form></div><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Customer</th><th>Created by</th><th>Payment</th><th class="right">Total</th><th class="right">Balance</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><a class="invoice-link" href="invoice.php?id=<?=$r['id']?>"><?=h($r['invoice_no'])?></a><small class="table-sub"><?=date('d M Y, H:i',strtotime($r['created_at']))?></small></td><td><?=h($r['customer'])?></td><td><?=h($r['staff']??'—')?></td><td><span class="badge soft"><?=h($r['payment_method'])?></span></td><td class="right strong"><?=money($r['total'])?></td><td class="right <?= $r['balance']>0?'danger-text':'success-text'?>"><?=money($r['balance'])?></td><td><a class="text-link" href="invoice.php?id=<?=$r['id']?>">View →</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="empty">No sales found.</td></tr><?php endif;?></tbody></table></div></section><?php layout_end();?>
